      {"id": "s03", "stage": "도입", "block": "review", "data": {"title": "지난 시간 떠올리기", "from": "u5_l12", "items": [{"q": "마음을 전하는 글을 쓸 때 어떤 태도가 필요한가요?", "a": "읽을 사람의 마음을 헤아리고 진심을 담는다"}, {"q": "전학 가는 친구에게 전하면 좋은 마음은 무엇인가요?", "a": "헤어짐이 아쉬운 마음"}, {"q": "편지를 받으면 무엇을 쓰나요?", "a": "답장"}]}, "suggested_extras": ["q_k14_last"], "tnote": {"ask": ["마음을 잘 전하는 태도는 무엇이었나요?", "편지를 받으면 무엇을 썼나요?"], "watch": "실천 차시와 사이가 벌어지면 태도 셋이 흐려진다 — 셋만 다시 짚는다", "min": 3}},
      {"id": "s04", "stage": "도입", "block": "motivate", "data": {"scene_title": "펭이가 쓴 쪽지를 곰이가 갸웃하며 봐요", "kids": [{"face": "🐧", "label": "펭이\n\"내일 꼭 갈께.\" 라고 썼어."}, {"face": "🐻", "label": "곰이\n\"소리는 그런데 글자는 다르대.\""}], "question": "소리와 글자가 다른 말이 있어요. 어떻게 적어야 할까요?", "img": "assets/photo/korean/unit5_wrapup.jpg"}, "suggested_extras": ["q_k14_sound", "x_k14_sound", "r_k14_note"], "tnote": {"ask": ["소리 나는 대로 적으면 될까요?", "소리와 글자가 다른 말을 만난 적이 있나요?"], "watch": "소리대로 적는 것이 맞다고 여기는 아이 — 오늘 규칙을 배운다고 짚는다", "min": 4}},
      {"id": "s05", "stage": "전개", "block": "concept", "data": {"title": "마음을 전하는 글, 기억나요", "content": "**받는 사람·쓴 사람·상황·마음**을 쓴다.\n웃어른께는 **높임 표현**을 쓴다.\n마음 나타내는 말은 **다양하게** 쓴다.", "note": "👉 세 가지를 손가락으로 세며 함께 말해 보세요."}, "suggested_extras": ["t_k14_check", "q_k14_back"], "tnote": {"ask": ["글에 들어갈 것은 무엇이었나요?", "웃어른께는 무엇을 썼나요?"], "watch": "높임 자국을 하나만 대는 아이 — 세 자국 판을 다시 보여 준다", "min": 4}},
      {"id": "s06", "stage": "전개", "block": "concept", "data": {"title": "성격 파악 방법도 기억나요", "content": "인물을 **수식하는 말** 찾기\n상황 속 **말과 행동** 살피기\n그림책은 **표정·몸짓**도 단서", "note": "👉 세 방법을 앞 항목의 판에서 그대로 옮겨 짚어 주세요."}, "suggested_extras": ["q_k14_back", "c_k14_note"], "tnote": {"ask": ["성격 파악 방법 세 가지는 무엇인가요?", "그림책에서 하나가 더 있었어요. 무엇인가요?"], "watch": "두 방법만 기억하는 아이 — 그림책 항목을 되짚어 준다", "min": 4}},
      {"id": "s07", "stage": "전개", "block": "concept", "data": {"title": "헷갈리는 표기를 알아봐요", "content": "\"내가 할게.\"의 **-ㄹ게**는\n소리는 [께]로 나지만 글로 쓸 때는 **'게'**로 적어요.\n왼쪽이 바른 표기, 오른쪽이 잘못된 표기예요.\n갈게 ↔ 갈께\n할게 ↔ 할께\n지킬게 ↔ 지킬께\n볼게 ↔ 볼께\n갈게 ↔ 갈껄", "note": "👉 약속·의지를 나타내는 말이라는 것을 함께 짚어 주세요."}, "suggested_extras": ["q_k14_sound", "t_k14_rule"], "tnote": {"ask": ["소리는 어떻게 나나요?", "글로 쓸 때는 어떻게 적나요?"], "watch": "소리와 글자를 같게 맞추려는 아이 — 왼쪽 줄만 소리 내어 읽힌다", "min": 5}},
      {"id": "s08", "stage": "전개", "block": "misconception", "data": {"title": "이런 생각을 조심해요", "label": "자주 하는 생각", "wrong": "소리 나는 대로 적으면 된다고 여긴다. 그래서 **갈께**라고 적는다.", "right": "약속이나 의지를 나타내는 **-ㄹ게**는 [께]로 소리 나도 **'게'**로 적어요. \"도와줄게\", \"지킬게요\"처럼요.", "hint": "왼쪽 줄만 가려 놓고 소리 내어 읽어 보게 하면 스스로 알아챕니다."}, "suggested_extras": ["x_k14_sound", "t_k14_rule"], "tnote": {"ask": ["소리 나는 대로 적으면 무엇이 어긋나나요?", "바르게 적은 것은 어느 쪽인가요?"], "watch": "소리대로 적으려는 아이 — 바른 표기만 모아 다시 읽힌다", "min": 5}},
      {"id": "s09", "stage": "기본문제", "block": "basic_problem", "data": {"title": "마음을 잘 전하는 방법 고르기", "scenario": {"icon": "💗", "body": "세 가지가 나란히 있어요."}, "question": "전하고 싶은 마음을 구체적으로 쓴다 · '고마워'만 여러 번 반복한다 · 마음과 상관없이 길게만 쓴다 가운데 알맞은 방법은 무엇일까요?", "answer": "전하고 싶은 마음을 구체적으로 쓴다", "note": "풀이: 받는 사람이 그 일을 **또렷이** 떠올릴 수 있어야 마음이 전해져요."}, "suggested_extras": ["t_k14_check", "q_k14_back"]},
      {"id": "s10", "stage": "기본문제", "block": "basic_problem", "data": {"title": "성격 낱말과 뜻 잇기", "scenario": {"icon": "📖", "body": "낱말과 뜻을 이어요."}, "question": "\"끈기 있다\"는 어떤 뜻일까요?", "answer": "쉽게 포기하지 않고 견딘다", "note": "풀이: \"다정하다\"는 **정이 많다**, \"정직하다\"는 **거짓 없이 바르고 솔직하다**예요."}, "suggested_extras": ["c_k14_note", "g_k14_bingo"]},
      {"id": "s11", "stage": "기본문제", "block": "basic_problem", "data": {"title": "바르게 쓴 것 고르기", "scenario": {"icon": "✍️", "body": "세 가지 가운데 하나만 바른 표기예요."}, "question": "내일 꼭 갈게. · 내일 꼭 갈께. · 내일 꼭 갈껄. 가운데 바르게 쓴 것은 무엇일까요?", "answer": "내일 꼭 갈게.", "note": "풀이: 약속·의지를 나타낼 때는 소리가 [께]라도 **'게'**로 적어요."}, "suggested_extras": ["q_k14_sound", "t_k14_rule"]},
      {"id": "s12", "stage": "기본문제", "block": "leveled_problem", "data": {"title": "바른 표기를 더 살펴봐요", "levels": {"기본": {"q": "세 문장을 소리 내어 읽어 봐요. 모두 바르게 쓴 문장이에요.\n① 제 방 청소는 제가 할게요.\n② 다음에는 약속을 꼭 지킬게요.\n③ 문제가 없는지 잘 살펴볼게.", "a": "세 줄을 또박또박 읽으면 정답", "steps": ["번호를 따라 한 줄씩 읽는다", "소리가 어떻게 나는지 들어 본다", "글자가 어떻게 적혔는지 본다", "소리는 [께]라도 '게'로 적혀 있다"]}, "도전": {"q": "세 문장에서 **약속이나 의지**를 나타내는 말을 찾아 말해 봐요.", "a": "할게요 · 지킬게요 · 살펴볼게", "steps": ["각 줄에서 끝맺는 말을 찾는다", "무엇을 하겠다는 뜻인지 생각한다", "약속·의지를 나타내는 말을 고른다", "세 낱말을 모두 찾는다"]}, "심화": {"q": "약속이나 의지를 나타내는 문장을 **하나 더** 지어 봐요.", "a": "여러 답 (예: 내일은 일찍 일어날게요)", "open": true}}}, "suggested_extras": ["e_k14_more", "t_k14_rule"], "tnote": {"ask": ["약속을 나타내는 말을 찾았나요?", "새로 지은 문장을 읽어 볼까요?"], "watch": "문장을 못 짓는 아이 — 오늘 하겠다고 마음먹은 일을 먼저 말하게 한다", "min": 7}},
      {"id": "s13", "stage": "응용문제", "block": "offline_activity", "data": {"title": "낱말 다지기와 글씨 쓰기", "type": "pair", "goal": "성격 낱말의 뜻을 이어 보고 배운 낱말을 또박또박 따라 쓰기", "steps": ["짝과 낱말 카드와 뜻 카드를 섞어 놓는다", "낱말과 뜻을 이어 짝을 맞춘다", "칸 공책에 정직·마음·배려 세 낱말을 또박또박 따라 쓴다", "짝과 바꾸어 읽고 잘 쓴 글자에 동그라미를 쳐 준다"], "materials": ["낱말 카드 6장·뜻 카드 6장(짝마다)", "칸 공책", "연필"], "minutes": 12}, "suggested_extras": ["g_k14_bingo", "c_k14_card"], "tnote": {"ask": ["낱말과 뜻을 다 이었나요?", "가장 또박또박 쓴 글자는 무엇인가요?"], "watch": "빨리 쓰고 덮는 아이 — 짝이 동그라미를 쳐 줄 때까지 기다리게 한다", "min": 12}},
      {"id": "s14", "stage": "응용문제", "block": "real_world", "data": {"title": "생활 속에서 실천해요", "scenario": {"icon": "💌", "body": "오늘부터 한 가지씩."}, "content": "인물의 성격을 파악하며 이야기를 읽고, 고마운 사람에게 **마음을 전하는 글**을 써 봐요. 한 번에 다 하지 않아도 돼요. 오늘부터 **한 가지씩** 하면 돼요."}, "suggested_extras": ["r_k14_note", "q_k14_life"]},
      {"id": "s15", "stage": "응용문제", "block": "advanced_problem", "data": {"title": "왜 소리대로 적지 않을까요", "context": "펭이가 물었어요. \"소리대로 적으면 읽기 쉽지 않아?\"", "challenge": "소리와 다르게 적는 말이 있는 까닭은 무엇일까요? 짝에게 말해 봐요.", "note": "풀이: 여러 답이 있어요. 사람마다 소리가 조금씩 달라도 **같은 모양으로 적으면** 누구나 뜻을 바로 알 수 있어요. 글자는 **뜻을 지키는 약속**이거든요."}, "suggested_extras": ["x_k14_sound", "e_k14_more", "q_k14_sound"], "tnote": {"ask": ["사람마다 소리가 조금씩 다르면 어떻게 될까요?", "같은 모양으로 적으면 무엇이 좋을까요?"], "watch": "\"그냥 규칙\"이라고 답하는 아이 — 뜻을 지키는 약속임을 짚어 준다", "min": 6}},
      {"id": "s16", "stage": "정리", "block": "exit_ticket", "data": {"title": "오늘 확인해요", "items": [{"q": "\"내일 꼭 갈게.\"의 -ㄹ게는 소리가 어떻게 나나요?", "a": "[께]로 나지만 '게'로 적는다"}, {"q": "\"끈기 있다\"는 어떤 뜻인가요?", "a": "쉽게 포기하지 않고 견딘다"}, {"q": "마음을 잘 전하려면 마음을 어떻게 써야 하나요?", "a": "구체적으로"}], "self": ["잘 알겠어요", "조금 헷갈려요", "다시 배우고 싶어요"]}, "suggested_extras": []},
      {"id": "s17", "stage": "정리", "block": "summary", "data": {"title": "오늘 배운 것", "points": ["마음은 **구체적으로** 써야 잘 전해진다.", "약속·의지를 나타내는 **-ㄹ게**는 [께]로 소리 나도 **'게'**로 적는다.", "성격 낱말의 뜻을 알고 바른 **글씨**로 또박또박 쓴다."], "arrows": ["구체적으로", "바른 표기", "바른 글씨"]}, "suggested_extras": ["t_k14_rule", "c_k14_note"]},
      {"id": "s18", "stage": "정리", "block": "self_assessment", "data": {"title": "스스로 점검해요", "items": ["📚 지식·이해 — 소리와 다르게 적는 말을 말할 수 있나요?", "🔧 과정·기능 — 성격 낱말과 뜻을 이을 수 있었나요?", "💛 가치·태도 — 글씨를 또박또박 쓰려고 했나요?"], "prompts": ["5단원에서 가장 마음에 남은 것은 무엇이었나요?"]}, "suggested_extras": ["c_k14_note", "q_k14_life"]},
      {"id": "s19", "stage": "정리", "block": "next_lesson", "data": {"title": "다음 시간에는", "preview": "5단원을 마쳤어요. 다음 단원에서도 이야기를 읽고 생각과 마음을 나누어 봐요. 오늘 배운 것을 생활에서 이어 가요.", "emoji": "🌱"}, "suggested_extras": ["r_k14_note", "b_k14_book"]}
